-- Medivo database setup: all migrations plus the course catalogue, for a NEW Supabase project.
-- Generated by scripts/build-setup-sql.sh. Do not edit by hand; run it once in the SQL Editor.

-- ===== supabase/migrations/20261028000000_foundation.sql =====
-- Medivo foundation schema.
-- Hierarchy: universities → programs → curriculum_versions → courses (per study year) → topics → learning content.
-- Security model:
--   * Published catalogue metadata is public.
--   * Premium learning content is only readable with an active entitlement (has_course_access).
--   * Answer keys live in their own table without any student SELECT policy; answers are checked by
--     submit_answer(), which runs as definer and only reveals the key after a recorded attempt.
--   * Students read and write only their own progress rows.

create extension if not exists pgcrypto;

-- ---------------------------------------------------------------------------
-- Enums
-- ---------------------------------------------------------------------------
create type public.publication_status as enum ('draft', 'published', 'archived');
create type public.user_role as enum ('student', 'admin');
create type public.question_type as enum ('single_choice');
create type public.practice_mode as enum ('topic', 'mixed', 'exam', 'incorrect');
create type public.rights_status as enum ('unknown', 'permission_requested', 'licensed', 'own_work', 'public_domain');
create type public.exam_type as enum ('regular', 'resit', 'midterm', 'practice');
create type public.entitlement_scope as enum ('course', 'program');
create type public.entitlement_source as enum ('subscription', 'purchase', 'manual');

-- ---------------------------------------------------------------------------
-- Catalogue
-- ---------------------------------------------------------------------------
create table public.universities (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  name text not null,
  short_name text,
  created_at timestamptz not null default now()
);

create table public.programs (
  id uuid primary key default gen_random_uuid(),
  university_id uuid not null references public.universities (id) on delete restrict,
  slug text not null,
  name text not null,
  degree_level text not null default 'bachelor',
  created_at timestamptz not null default now(),
  unique (university_id, slug)
);

create table public.curriculum_versions (
  id uuid primary key default gen_random_uuid(),
  program_id uuid not null references public.programs (id) on delete restrict,
  label text not null,
  is_current boolean not null default false,
  valid_from date,
  created_at timestamptz not null default now(),
  unique (program_id, label)
);
-- At most one current curriculum per program.
create unique index curriculum_versions_one_current on public.curriculum_versions (program_id) where is_current;

create table public.courses (
  id uuid primary key default gen_random_uuid(),
  curriculum_version_id uuid not null references public.curriculum_versions (id) on delete restrict,
  slug text not null,
  title text not null,
  study_year smallint not null check (study_year between 1 and 6),
  ec numeric(4, 1) check (ec is null or ec > 0),
  description text,
  sort_order integer not null default 0,
  hero_image text,
  status public.publication_status not null default 'draft',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (curriculum_version_id, slug)
);
create index courses_curriculum_year on public.courses (curriculum_version_id, study_year, sort_order);

create table public.topics (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references public.courses (id) on delete cascade,
  parent_id uuid references public.topics (id) on delete cascade,
  slug text not null,
  title text not null,
  sort_order integer not null default 0,
  status public.publication_status not null default 'draft',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  unique (course_id, slug)
);
create index topics_course on public.topics (course_id, parent_id, sort_order);

create table public.learning_objectives (
  id uuid primary key default gen_random_uuid(),
  topic_id uuid not null references public.topics (id) on delete cascade,
  body text not null,
  source text,
  sort_order integer not null default 0,
  status public.publication_status not null default 'draft',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index learning_objectives_topic on public.learning_objectives (topic_id, sort_order);

-- Summaries are structured JSON blocks (validated by the app with Zod), never raw HTML.
create table public.summaries (
  id uuid primary key default gen_random_uuid(),
  topic_id uuid not null references public.topics (id) on delete cascade,
  title text not null,
  content jsonb not null default '[]'::jsonb check (jsonb_typeof(content) = 'array'),
  is_premium boolean not null default true,
  pdf_path text,
  pdf_download_allowed boolean not null default false,
  reviewed_by uuid references auth.users (id),
  reviewed_at timestamptz,
  status public.publication_status not null default 'draft',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- AI-assisted or not, nothing is published without a recorded review.
  constraint summaries_reviewed_before_publish check (status <> 'published' or reviewed_at is not null)
);
create index summaries_topic on public.summaries (topic_id);

create table public.exams (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references public.courses (id) on delete cascade,
  exam_year smallint not null check (exam_year between 1990 and 2100),
  exam_type public.exam_type not null default 'regular',
  title text,
  question_count integer check (question_count is null or question_count >= 0),
  has_explanations boolean not null default false,
  source text not null,
  rights_status public.rights_status not null default 'unknown',
  is_premium boolean not null default true,
  status public.publication_status not null default 'draft',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  -- Exams without cleared rights can never be published.
  constraint exams_rights_before_publish check (
    status <> 'published' or rights_status in ('licensed', 'own_work', 'public_domain')
  )
);
create index exams_course on public.exams (course_id, exam_year desc);

create table public.questions (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references public.courses (id) on delete cascade,
  topic_id uuid not null references public.topics (id) on delete restrict,
  exam_id uuid references public.exams (id) on delete set null,
  type public.question_type not null default 'single_choice',
  stem text not null,
  image_path text,
  image_alt text,
  difficulty smallint check (difficulty between 1 and 5),
  source text not null,
  copyright_status public.rights_status not null default 'unknown',
  is_premium boolean not null default true,
  reviewed_by uuid references auth.users (id),
  reviewed_at timestamptz,
  status public.publication_status not null default 'draft',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint questions_publishable check (
    status <> 'published'
    or (reviewed_at is not null and copyright_status in ('licensed', 'own_work', 'public_domain'))
  )
);
create index questions_topic on public.questions (topic_id) where status = 'published';
create index questions_course on public.questions (course_id);

-- Options are safe to show before answering; they carry no correctness flag.
create table public.question_options (
  id uuid primary key default gen_random_uuid(),
  question_id uuid not null references public.questions (id) on delete cascade,
  label text not null check (label ~ '^[A-Z]$'),
  body text not null,
  sort_order integer not null default 0,
  unique (question_id, label)
);

-- The answer key. No student policy: only admins and security-definer functions can read it.
create table public.question_answer_keys (
  question_id uuid primary key references public.questions (id) on delete cascade,
  correct_option_id uuid not null references public.question_options (id) on delete restrict,
  explanation text not null,
  concept text,
  -- { "<option uuid>": "why this option is wrong" }
  option_feedback jsonb not null default '{}'::jsonb check (jsonb_typeof(option_feedback) = 'object')
);

-- ---------------------------------------------------------------------------
-- Accounts
-- ---------------------------------------------------------------------------
create table public.profiles (
  id uuid primary key references auth.users (id) on delete cascade,
  full_name text,
  university_id uuid references public.universities (id) on delete set null,
  study_year smallint check (study_year is null or study_year between 1 and 6),
  role public.user_role not null default 'student',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);

create table public.stripe_customers (
  user_id uuid primary key references auth.users (id) on delete cascade,
  stripe_customer_id text not null unique
);

-- Sellable products. Prices live in Stripe so they stay configurable without a deploy.
create table public.products (
  id uuid primary key default gen_random_uuid(),
  slug text not null unique,
  name text not null,
  scope public.entitlement_scope not null,
  course_id uuid references public.courses (id) on delete restrict,
  program_id uuid references public.programs (id) on delete restrict,
  stripe_product_id text unique,
  active boolean not null default false,
  constraint products_scope_target check (
    (scope = 'course' and course_id is not null and program_id is null)
    or (scope = 'program' and program_id is not null and course_id is null)
  )
);

create table public.subscriptions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  product_id uuid references public.products (id) on delete set null,
  stripe_subscription_id text not null unique,
  stripe_price_id text,
  status text not null,
  current_period_end timestamptz,
  cancel_at_period_end boolean not null default false,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index subscriptions_user on public.subscriptions (user_id);

create table public.entitlements (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  scope public.entitlement_scope not null,
  course_id uuid references public.courses (id) on delete cascade,
  program_id uuid references public.programs (id) on delete cascade,
  source public.entitlement_source not null,
  subscription_id uuid references public.subscriptions (id) on delete cascade,
  starts_at timestamptz not null default now(),
  expires_at timestamptz,
  created_at timestamptz not null default now(),
  constraint entitlements_scope_target check (
    (scope = 'course' and course_id is not null and program_id is null)
    or (scope = 'program' and program_id is not null and course_id is null)
  )
);
create index entitlements_user on public.entitlements (user_id);

-- ---------------------------------------------------------------------------
-- Progress
-- ---------------------------------------------------------------------------
create table public.course_visits (
  user_id uuid not null references auth.users (id) on delete cascade,
  course_id uuid not null references public.courses (id) on delete cascade,
  last_visited_at timestamptz not null default now(),
  primary key (user_id, course_id)
);

create table public.objective_completions (
  user_id uuid not null references auth.users (id) on delete cascade,
  objective_id uuid not null references public.learning_objectives (id) on delete cascade,
  completed_at timestamptz not null default now(),
  primary key (user_id, objective_id)
);

create table public.practice_sessions (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  course_id uuid not null references public.courses (id) on delete cascade,
  mode public.practice_mode not null,
  topic_ids uuid[] not null default '{}',
  question_ids uuid[] not null,
  time_limit_seconds integer check (time_limit_seconds is null or time_limit_seconds > 0),
  started_at timestamptz not null default now(),
  finished_at timestamptz
);
create index practice_sessions_user on public.practice_sessions (user_id, started_at desc);

create table public.question_attempts (
  id uuid primary key default gen_random_uuid(),
  user_id uuid not null references auth.users (id) on delete cascade,
  session_id uuid not null references public.practice_sessions (id) on delete cascade,
  question_id uuid not null references public.questions (id) on delete cascade,
  selected_option_id uuid not null references public.question_options (id) on delete cascade,
  is_correct boolean not null,
  answered_at timestamptz not null default now(),
  -- One answer per question per session: retries and double clicks cannot skew results.
  unique (session_id, question_id)
);
create index question_attempts_user_question on public.question_attempts (user_id, question_id, answered_at desc);

create table public.bookmarks (
  user_id uuid not null references auth.users (id) on delete cascade,
  question_id uuid not null references public.questions (id) on delete cascade,
  created_at timestamptz not null default now(),
  primary key (user_id, question_id)
);

-- ---------------------------------------------------------------------------
-- Helpers
-- ---------------------------------------------------------------------------
create or replace function public.touch_updated_at() returns trigger
language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end $$;

do $$
declare t text;
begin
  foreach t in array array['courses', 'topics', 'learning_objectives', 'summaries', 'exams', 'questions', 'profiles', 'subscriptions']
  loop
    execute format('create trigger %I_touch before update on public.%I for each row execute function public.touch_updated_at()', t, t);
  end loop;
end $$;

create or replace function public.is_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles where id = auth.uid() and role = 'admin');
$$;

create or replace function public.has_course_access(p_course_id uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.is_admin() or exists (
    select 1
    from public.entitlements e
    join public.courses c on c.id = p_course_id
    join public.curriculum_versions cv on cv.id = c.curriculum_version_id
    where e.user_id = auth.uid()
      and e.starts_at <= now()
      and (e.expires_at is null or e.expires_at > now())
      and (e.course_id = p_course_id or e.program_id = cv.program_id)
  );
$$;

create or replace function public.handle_new_user() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  insert into public.profiles (id, full_name)
  values (new.id, nullif(trim(new.raw_user_meta_data ->> 'full_name'), ''));
  return new;
end $$;

create trigger on_auth_user_created
  after insert on auth.users
  for each row execute function public.handle_new_user();

-- ---------------------------------------------------------------------------
-- Row Level Security
-- ---------------------------------------------------------------------------
alter table public.universities enable row level security;
alter table public.programs enable row level security;
alter table public.curriculum_versions enable row level security;
alter table public.courses enable row level security;
alter table public.topics enable row level security;
alter table public.learning_objectives enable row level security;
alter table public.summaries enable row level security;
alter table public.exams enable row level security;
alter table public.questions enable row level security;
alter table public.question_options enable row level security;
alter table public.question_answer_keys enable row level security;
alter table public.profiles enable row level security;
alter table public.stripe_customers enable row level security;
alter table public.products enable row level security;
alter table public.subscriptions enable row level security;
alter table public.entitlements enable row level security;
alter table public.course_visits enable row level security;
alter table public.objective_completions enable row level security;
alter table public.practice_sessions enable row level security;
alter table public.question_attempts enable row level security;
alter table public.bookmarks enable row level security;

-- Public catalogue
create policy "catalogue readable" on public.universities for select using (true);
create policy "catalogue readable" on public.programs for select using (true);
create policy "catalogue readable" on public.curriculum_versions for select using (true);
create policy "published courses readable" on public.courses for select using (status = 'published' or public.is_admin());
create policy "published topics readable" on public.topics for select using (
  (status = 'published' and exists (select 1 from public.courses c where c.id = course_id and c.status = 'published'))
  or public.is_admin()
);
create policy "published objectives readable" on public.learning_objectives for select using (
  (status = 'published' and exists (select 1 from public.topics t where t.id = topic_id and t.status = 'published'))
  or public.is_admin()
);
create policy "exam metadata readable" on public.exams for select using (status = 'published' or public.is_admin());
create policy "products readable" on public.products for select using (active or public.is_admin());

-- Premium content
create policy "summaries readable with access" on public.summaries for select using (
  public.is_admin() or (
    status = 'published'
    and exists (
      select 1 from public.topics t
      where t.id = topic_id and t.status = 'published'
        and (not is_premium or public.has_course_access(t.course_id))
    )
  )
);
create policy "questions readable with access" on public.questions for select using (
  public.is_admin() or (
    status = 'published' and auth.uid() is not null
    and (not is_premium or public.has_course_access(course_id))
  )
);
create policy "options follow their question" on public.question_options for select using (
  exists (select 1 from public.questions q where q.id = question_id)
);
create policy "answer keys admin only" on public.question_answer_keys for select using (public.is_admin());

-- Admin management of content
do $$
declare t text;
begin
  foreach t in array array['universities', 'programs', 'curriculum_versions', 'courses', 'topics', 'learning_objectives',
                           'summaries', 'exams', 'questions', 'question_options', 'question_answer_keys', 'products', 'entitlements']
  loop
    execute format('create policy "admins manage" on public.%I for all using (public.is_admin()) with check (public.is_admin())', t);
  end loop;
end $$;

-- Profiles: own row; the role column is not writable by students (see grants below).
create policy "own profile readable" on public.profiles for select using (id = auth.uid() or public.is_admin());
create policy "own profile updatable" on public.profiles for update using (id = auth.uid()) with check (id = auth.uid());
create policy "admins manage profiles" on public.profiles for update using (public.is_admin()) with check (public.is_admin());
revoke update on public.profiles from authenticated, anon;
grant update (full_name, university_id, study_year) on public.profiles to authenticated;

-- Billing: read own; writes only by the service role (Stripe webhook).
create policy "own subscriptions readable" on public.subscriptions for select using (user_id = auth.uid() or public.is_admin());
create policy "own entitlements readable" on public.entitlements for select using (user_id = auth.uid() or public.is_admin());

-- Progress: own rows only.
create policy "own visits" on public.course_visits for all using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own objective completions" on public.objective_completions for all
  using (user_id = auth.uid()) with check (user_id = auth.uid());
create policy "own bookmarks" on public.bookmarks for all using (user_id = auth.uid()) with check (user_id = auth.uid());
-- Sessions and attempts are created only through the functions below, so students get read access only.
create policy "own sessions readable" on public.practice_sessions for select using (user_id = auth.uid());
create policy "own attempts readable" on public.question_attempts for select using (user_id = auth.uid());

-- ---------------------------------------------------------------------------
-- Practice engine
-- ---------------------------------------------------------------------------

-- Number of published questions per topic. Counts are not premium, so anyone may see them.
create or replace function public.topic_question_counts(p_course_id uuid)
returns table (topic_id uuid, question_count bigint)
language sql stable security definer set search_path = public as $$
  select q.topic_id, count(*)
  from public.questions q
  join public.courses c on c.id = q.course_id and c.status = 'published'
  where q.course_id = p_course_id and q.status = 'published'
  group by q.topic_id;
$$;

create or replace function public.start_practice_session(
  p_course_id uuid,
  p_mode public.practice_mode,
  p_topic_ids uuid[] default '{}',
  p_limit integer default 20,
  p_time_limit_seconds integer default null
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_user uuid := auth.uid();
  v_ids uuid[];
  v_session uuid;
begin
  if v_user is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 200 then
    raise exception 'invalid_limit' using errcode = '22023';
  end if;
  if p_mode = 'topic' and coalesce(array_length(p_topic_ids, 1), 0) <> 1 then
    raise exception 'topic_mode_needs_one_topic' using errcode = '22023';
  end if;

  select array_agg(id) into v_ids from (
    select q.id
    from public.questions q
    join public.topics t on t.id = q.topic_id
    where q.course_id = p_course_id
      and q.status = 'published'
      and (not q.is_premium or public.has_course_access(p_course_id))
      -- A subtopic counts as part of its parent topic.
      and (coalesce(array_length(p_topic_ids, 1), 0) = 0 or q.topic_id = any (p_topic_ids) or t.parent_id = any (p_topic_ids))
      and (
        p_mode <> 'incorrect' or exists (
          select 1 from (
            select distinct on (a.question_id) a.question_id, a.is_correct
            from public.question_attempts a
            where a.user_id = v_user and a.question_id = q.id
            order by a.question_id, a.answered_at desc
          ) latest where not latest.is_correct
        )
      )
    order by case when p_mode = 'topic' then t.sort_order else 0 end, case when p_mode = 'topic' then q.created_at end, random()
    limit p_limit
  ) picked;

  if v_ids is null then
    raise exception 'no_questions_available' using errcode = 'P0002';
  end if;

  insert into public.practice_sessions (user_id, course_id, mode, topic_ids, question_ids, time_limit_seconds)
  values (v_user, p_course_id, p_mode, coalesce(p_topic_ids, '{}'), v_ids,
          case when p_mode = 'exam' then p_time_limit_seconds end)
  returning id into v_session;

  return v_session;
end $$;

-- Records one answer. Idempotent: a repeated submit returns the first recorded answer.
-- In exam mode feedback stays hidden until finish_practice_session.
create or replace function public.submit_answer(p_session_id uuid, p_question_id uuid, p_option_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_user uuid := auth.uid();
  v_session public.practice_sessions;
  v_key public.question_answer_keys;
  v_attempt public.question_attempts;
begin
  select * into v_session from public.practice_sessions where id = p_session_id and user_id = v_user;
  if not found then
    raise exception 'session_not_found' using errcode = 'P0002';
  end if;
  if v_session.finished_at is not null then
    raise exception 'session_finished' using errcode = '22023';
  end if;
  if not (p_question_id = any (v_session.question_ids)) then
    raise exception 'question_not_in_session' using errcode = '22023';
  end if;
  if v_session.mode = 'exam' and v_session.time_limit_seconds is not null
     and now() > v_session.started_at + make_interval(secs => v_session.time_limit_seconds) then
    raise exception 'time_expired' using errcode = '22023';
  end if;
  if not exists (select 1 from public.question_options where id = p_option_id and question_id = p_question_id) then
    raise exception 'invalid_option' using errcode = '22023';
  end if;

  select * into v_key from public.question_answer_keys where question_id = p_question_id;
  if not found then
    raise exception 'answer_key_missing' using errcode = 'P0002';
  end if;

  insert into public.question_attempts (user_id, session_id, question_id, selected_option_id, is_correct)
  values (v_user, p_session_id, p_question_id, p_option_id, p_option_id = v_key.correct_option_id)
  on conflict (session_id, question_id) do nothing;

  select * into v_attempt from public.question_attempts where session_id = p_session_id and question_id = p_question_id;

  if v_session.mode = 'exam' then
    return jsonb_build_object('recorded', true, 'selected_option_id', v_attempt.selected_option_id);
  end if;

  return jsonb_build_object(
    'recorded', true,
    'selected_option_id', v_attempt.selected_option_id,
    'is_correct', v_attempt.is_correct,
    'correct_option_id', v_key.correct_option_id,
    'explanation', v_key.explanation,
    'concept', v_key.concept,
    'option_feedback', v_key.option_feedback
  );
end $$;

-- Closes a session and returns the score plus a full review (answer keys included).
create or replace function public.finish_practice_session(p_session_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_user uuid := auth.uid();
  v_session public.practice_sessions;
  v_review jsonb;
begin
  select * into v_session from public.practice_sessions where id = p_session_id and user_id = v_user;
  if not found then
    raise exception 'session_not_found' using errcode = 'P0002';
  end if;

  update public.practice_sessions set finished_at = coalesce(finished_at, now()) where id = p_session_id;

  select coalesce(jsonb_agg(jsonb_build_object(
      'question_id', qid,
      'selected_option_id', a.selected_option_id,
      'is_correct', coalesce(a.is_correct, false),
      'correct_option_id', k.correct_option_id,
      'explanation', k.explanation,
      'concept', k.concept,
      'option_feedback', k.option_feedback
    ) order by ord), '[]'::jsonb)
  into v_review
  from unnest(v_session.question_ids) with ordinality as s(qid, ord)
  left join public.question_attempts a on a.session_id = p_session_id and a.question_id = s.qid
  left join public.question_answer_keys k on k.question_id = s.qid;

  return jsonb_build_object(
    'total', coalesce(array_length(v_session.question_ids, 1), 0),
    'answered', (select count(*) from public.question_attempts where session_id = p_session_id),
    'correct', (select count(*) from public.question_attempts where session_id = p_session_id and is_correct),
    'review', v_review
  );
end $$;

-- Per-topic accuracy for the signed-in student (latest answer per question).
create or replace function public.my_topic_stats(p_course_id uuid)
returns table (topic_id uuid, answered bigint, correct bigint)
language sql stable security definer set search_path = public as $$
  select q.topic_id, count(*), count(*) filter (where latest.is_correct)
  from (
    select distinct on (a.question_id) a.question_id, a.is_correct
    from public.question_attempts a
    where a.user_id = auth.uid()
    order by a.question_id, a.answered_at desc
  ) latest
  join public.questions q on q.id = latest.question_id
  where q.course_id = p_course_id
  group by q.topic_id;
$$;

-- Supabase grants EXECUTE to anon through PUBLIC; the practice functions are for signed-in students only.
revoke execute on function public.start_practice_session(uuid, public.practice_mode, uuid[], integer, integer) from public, anon;
revoke execute on function public.submit_answer(uuid, uuid, uuid) from public, anon;
revoke execute on function public.finish_practice_session(uuid) from public, anon;
revoke execute on function public.my_topic_stats(uuid) from public, anon;
grant execute on function public.start_practice_session(uuid, public.practice_mode, uuid[], integer, integer) to authenticated;
grant execute on function public.submit_answer(uuid, uuid, uuid) to authenticated;
grant execute on function public.finish_practice_session(uuid) to authenticated;
grant execute on function public.my_topic_stats(uuid) to authenticated;

-- What a course offers, without revealing premium content: counts plus whether the viewer has access.
create or replace function public.course_content_overview(p_course_id uuid)
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'summaries', (select count(*) from public.summaries s join public.topics t on t.id = s.topic_id
                  where t.course_id = p_course_id and s.status = 'published' and t.status = 'published'),
    'objectives', (select count(*) from public.learning_objectives o join public.topics t on t.id = o.topic_id
                   where t.course_id = p_course_id and o.status = 'published' and t.status = 'published'),
    'exams', (select count(*) from public.exams e where e.course_id = p_course_id and e.status = 'published'),
    'questions', (select count(*) from public.questions q where q.course_id = p_course_id and q.status = 'published'),
    'has_access', public.has_course_access(p_course_id)
  )
  where exists (select 1 from public.courses where id = p_course_id and status = 'published');
$$;

-- ===== supabase/migrations/20261028000100_storage.sql =====
-- Private storage for course images and PDFs. Nothing in this bucket is public: files are served through
-- short-lived signed URLs, which Supabase only issues to users that pass the SELECT policy below.
-- Path convention: <course uuid>/free/<file> or <course uuid>/premium/<file>.
-- Skipped on plain Postgres (tests), where the storage schema does not exist.

do $migration$
begin
  if not exists (select 1 from information_schema.schemata where schema_name = 'storage') then
    raise notice 'storage schema not found, skipping storage setup';
    return;
  end if;

  insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
  values ('course-content', 'course-content', false, 20971520,
          array['image/png', 'image/jpeg', 'image/webp', 'image/svg+xml', 'application/pdf'])
  on conflict (id) do update set public = false;

  execute $p$
    create policy "course content readable with access" on storage.objects for select to authenticated using (
      bucket_id = 'course-content'
      and exists (
        select 1 from public.courses c
        where c.id::text = (storage.foldername(name))[1]
          and c.status = 'published'
          and ((storage.foldername(name))[2] = 'free' or public.has_course_access(c.id))
      )
    )
  $p$;
  execute $p$
    create policy "admins manage course content" on storage.objects for all to authenticated
      using (bucket_id = 'course-content' and public.is_admin())
      with check (bucket_id = 'course-content' and public.is_admin())
  $p$;
end
$migration$;

-- ===== supabase/migrations/20261029000000_admin_content.sql =====
-- Admin authoring: save a question with its options and answer key in one transaction.
-- Doing this through separate REST calls could leave a published question without an answer key.

create or replace function public.admin_save_question(p jsonb)
returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_id uuid := nullif(p ->> 'id', '')::uuid;
  v_labels text[];
  v_correct uuid;
  v_feedback jsonb := '{}'::jsonb;
  v_opt record;
begin
  if not public.is_admin() then
    raise exception 'not_admin' using errcode = '42501';
  end if;

  select array_agg(o ->> 'label' order by ord) into v_labels
  from jsonb_array_elements(p -> 'options') with ordinality as t(o, ord);
  if coalesce(array_length(v_labels, 1), 0) < 2 then
    raise exception 'need_two_options' using errcode = '22023';
  end if;
  if not (p ->> 'correct_label') = any (v_labels) then
    raise exception 'correct_option_missing' using errcode = '22023';
  end if;

  -- Fields first, as a draft: the final status is set at the end, once the answer key exists.
  if v_id is null then
    insert into public.questions (course_id, topic_id, exam_id, stem, image_path, image_alt, difficulty, source,
                                  copyright_status, is_premium, status)
    values ((p ->> 'course_id')::uuid, (p ->> 'topic_id')::uuid, nullif(p ->> 'exam_id', '')::uuid, p ->> 'stem',
            nullif(p ->> 'image_path', ''), nullif(p ->> 'image_alt', ''), nullif(p ->> 'difficulty', '')::smallint,
            p ->> 'source', (p ->> 'copyright_status')::public.rights_status, coalesce((p ->> 'is_premium')::boolean, true),
            'draft')
    returning id into v_id;
  else
    update public.questions set
      topic_id = (p ->> 'topic_id')::uuid,
      exam_id = nullif(p ->> 'exam_id', '')::uuid,
      stem = p ->> 'stem',
      image_path = nullif(p ->> 'image_path', ''),
      image_alt = nullif(p ->> 'image_alt', ''),
      difficulty = nullif(p ->> 'difficulty', '')::smallint,
      source = p ->> 'source',
      copyright_status = (p ->> 'copyright_status')::public.rights_status,
      is_premium = coalesce((p ->> 'is_premium')::boolean, true),
      status = 'draft'
    where id = v_id;
    if not found then
      raise exception 'question_not_found' using errcode = 'P0002';
    end if;
  end if;

  -- Options are matched by label, so existing answers keep pointing at the same option.
  insert into public.question_options (question_id, label, body, sort_order)
  select v_id, o ->> 'label', o ->> 'body', ord
  from jsonb_array_elements(p -> 'options') with ordinality as t(o, ord)
  on conflict (question_id, label) do update set body = excluded.body, sort_order = excluded.sort_order;

  select id into v_correct from public.question_options where question_id = v_id and label = p ->> 'correct_label';

  for v_opt in select id, label from public.question_options where question_id = v_id loop
    if coalesce(p -> 'option_feedback' ->> v_opt.label, '') <> '' then
      v_feedback := v_feedback || jsonb_build_object(v_opt.id::text, p -> 'option_feedback' ->> v_opt.label);
    end if;
  end loop;

  insert into public.question_answer_keys (question_id, correct_option_id, explanation, concept, option_feedback)
  values (v_id, v_correct, p ->> 'explanation', nullif(p ->> 'concept', ''), v_feedback)
  on conflict (question_id) do update set
    correct_option_id = excluded.correct_option_id,
    explanation = excluded.explanation,
    concept = excluded.concept,
    option_feedback = excluded.option_feedback;

  -- Removing an option that students already chose would silently delete their answers.
  if exists (
    select 1 from public.question_attempts a
    join public.question_options o on o.id = a.selected_option_id
    where o.question_id = v_id and not (o.label = any (v_labels))
  ) then
    raise exception 'option_in_use' using errcode = '22023';
  end if;
  delete from public.question_options where question_id = v_id and not (label = any (v_labels));

  update public.questions set
    reviewed_at = case when (p ->> 'reviewed')::boolean then coalesce(reviewed_at, now()) end,
    reviewed_by = case when (p ->> 'reviewed')::boolean then coalesce(reviewed_by, auth.uid()) end,
    status = (p ->> 'status')::public.publication_status
  where id = v_id;

  return v_id;
end $$;

revoke execute on function public.admin_save_question(jsonb) from public, anon;
grant execute on function public.admin_save_question(jsonb) to authenticated;

-- ===== supabase/migrations/20261029120000_question_types.sql =====
-- Question types as they appear on real exams, and whole exams in their original order.
--   single_choice    one correct option (as before)
--   multiple_choice  "more answers possible": all correct options and nothing else
--   dropdowns        list-box, matching and fill-in questions: one choice per item, partial credit per item
--   numeric          very-short-answer calculations, correct within a range
--   open             written answers; the student marks them against the answer model
-- Public, answer-free configuration lives in questions.content; everything that reveals the answer stays in
-- question_answer_keys, which students cannot read.

alter type public.question_type add value if not exists 'multiple_choice';
alter type public.question_type add value if not exists 'dropdowns';
alter type public.question_type add value if not exists 'numeric';
alter type public.question_type add value if not exists 'open';

-- Reconstructed exams do not always have a known year.
alter table public.exams alter column exam_year drop not null;

alter table public.questions
  add column content jsonb not null default '{}'::jsonb check (jsonb_typeof(content) = 'object'),
  add column context text,
  add column points numeric(5, 2) not null default 1 check (points > 0),
  add column exam_position integer;
create index questions_exam on public.questions (exam_id, exam_position);

alter table public.question_answer_keys
  alter column correct_option_id drop not null,
  add column answer jsonb not null default '{}'::jsonb check (jsonb_typeof(answer) = 'object');

alter table public.practice_sessions add column exam_id uuid references public.exams (id) on delete set null;

alter table public.question_attempts
  alter column selected_option_id drop not null,
  add column response jsonb not null default '{}'::jsonb,
  -- Null while an open answer still has to be marked by the student.
  add column score numeric(5, 2),
  add column max_score numeric(5, 2) not null default 1;
update public.question_attempts set score = case when is_correct then 1 else 0 end where score is null;

-- ---------------------------------------------------------------------------
-- Grading
-- ---------------------------------------------------------------------------

-- Checks that a response has the right shape for the question; raises invalid_answer otherwise.
create or replace function public.validate_response(p_question public.questions, p_response jsonb)
returns void
language plpgsql stable set search_path = public as $$
declare
  v_items jsonb := coalesce(p_question.content -> 'items', '[]'::jsonb);
  v_ids uuid[];
begin
  if p_response is null or jsonb_typeof(p_response) <> 'object' then
    raise exception 'invalid_answer' using errcode = '22023';
  end if;
  case p_question.type::text
    when 'single_choice' then
      if not exists (select 1 from public.question_options
                     where id = nullif(p_response ->> 'option_id', '')::uuid and question_id = p_question.id) then
        raise exception 'invalid_option' using errcode = '22023';
      end if;
    when 'multiple_choice' then
      if jsonb_typeof(p_response -> 'option_ids') <> 'array' or jsonb_array_length(p_response -> 'option_ids') = 0 then
        raise exception 'invalid_option' using errcode = '22023';
      end if;
      select array_agg(x::uuid) into v_ids from jsonb_array_elements_text(p_response -> 'option_ids') x;
      if exists (select 1 from unnest(v_ids) i
                 where not exists (select 1 from public.question_options o where o.id = i and o.question_id = p_question.id)) then
        raise exception 'invalid_option' using errcode = '22023';
      end if;
    when 'dropdowns' then
      if jsonb_typeof(p_response -> 'answers') <> 'array'
         or jsonb_array_length(p_response -> 'answers') <> jsonb_array_length(v_items) then
        raise exception 'invalid_answer' using errcode = '22023';
      end if;
      if exists (
        select 1 from jsonb_array_elements(p_response -> 'answers') with ordinality a(v, n)
        where jsonb_typeof(a.v) <> 'null'
          and not ((v_items -> (a.n::int - 1) -> 'choices') ? (a.v #>> '{}'))
      ) then
        raise exception 'invalid_answer' using errcode = '22023';
      end if;
    when 'numeric' then
      if jsonb_typeof(p_response -> 'value') <> 'string' or length(trim(p_response ->> 'value')) = 0
         or length(p_response ->> 'value') > 60 then
        raise exception 'invalid_answer' using errcode = '22023';
      end if;
    when 'open' then
      if jsonb_typeof(p_response -> 'text') <> 'string' or length(trim(p_response ->> 'text')) = 0
         or length(p_response ->> 'text') > 8000 then
        raise exception 'invalid_answer' using errcode = '22023';
      end if;
  end case;
end $$;

-- Score for a (validated) response. Null means the student marks it themselves (open questions).
create or replace function public.grade_response(p_question public.questions, p_key public.question_answer_keys, p_response jsonb)
returns numeric
language plpgsql stable set search_path = public as $$
declare
  v_items jsonb := coalesce(p_question.content -> 'items', '[]'::jsonb);
  v_n int;
  v_score numeric := 0;
  v_raw text;
  v_value numeric;
begin
  case p_question.type::text
    when 'single_choice' then
      return case when (p_response ->> 'option_id')::uuid = p_key.correct_option_id then p_question.points else 0 end;
    when 'multiple_choice' then
      -- Correct only when the chosen labels are exactly the key's labels.
      return case when (
        select coalesce(array_agg(o.label order by o.label), '{}')
        from public.question_options o
        where o.question_id = p_question.id and o.id in (select x::uuid from jsonb_array_elements_text(p_response -> 'option_ids') x)
      ) = (
        select coalesce(array_agg(l order by l), '{}') from jsonb_array_elements_text(p_key.answer -> 'labels') l
      ) then p_question.points else 0 end;
    when 'dropdowns' then
      v_n := jsonb_array_length(v_items);
      select coalesce(sum(coalesce((v_items -> (r.n::int - 1) ->> 'points')::numeric, p_question.points / v_n)), 0)
      into v_score
      from jsonb_array_elements(p_response -> 'answers') with ordinality r(v, n)
      where jsonb_typeof(r.v) = 'string' and r.v = p_key.answer -> 'answers' -> (r.n::int - 1);
      return round(least(v_score, p_question.points), 2);
    when 'numeric' then
      -- Accept a decimal comma and a unit after the number: "5,8 L/h" reads as 5.8.
      v_raw := substring(replace(replace(p_response ->> 'value', ' ', ''), ',', '.') from '-?[0-9]+(?:\.[0-9]+)?');
      if v_raw is null then
        return 0;
      end if;
      v_value := v_raw::numeric;
      return case when v_value between (p_key.answer ->> 'min')::numeric and (p_key.answer ->> 'max')::numeric
                  then p_question.points else 0 end;
    when 'open' then
      return null;
  end case;
  return 0;
end $$;

revoke execute on function public.validate_response(public.questions, jsonb) from public, anon, authenticated;
revoke execute on function public.grade_response(public.questions, public.question_answer_keys, jsonb) from public, anon, authenticated;

-- ---------------------------------------------------------------------------
-- Practice engine
-- ---------------------------------------------------------------------------

drop function public.start_practice_session(uuid, public.practice_mode, uuid[], integer, integer);

create or replace function public.start_practice_session(
  p_course_id uuid,
  p_mode public.practice_mode,
  p_topic_ids uuid[] default '{}',
  p_limit integer default 20,
  p_time_limit_seconds integer default null,
  p_exam_id uuid default null
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_user uuid := auth.uid();
  v_ids uuid[];
  v_session uuid;
begin
  if v_user is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 200 then
    raise exception 'invalid_limit' using errcode = '22023';
  end if;
  if p_exam_id is null and p_mode = 'topic' and coalesce(array_length(p_topic_ids, 1), 0) <> 1 then
    raise exception 'topic_mode_needs_one_topic' using errcode = '22023';
  end if;

  if p_exam_id is not null then
    -- A whole exam, in its original order.
    select array_agg(id order by exam_position, created_at) into v_ids from (
      select q.id, q.exam_position, q.created_at
      from public.questions q
      join public.exams e on e.id = q.exam_id and e.status = 'published'
      where q.exam_id = p_exam_id
        and q.course_id = p_course_id
        and q.status = 'published'
        and (not q.is_premium or public.has_course_access(p_course_id))
      order by q.exam_position, q.created_at
      limit p_limit
    ) picked;
  else
    select array_agg(id) into v_ids from (
      select q.id
      from public.questions q
      join public.topics t on t.id = q.topic_id
      where q.course_id = p_course_id
        and q.status = 'published'
        and (not q.is_premium or public.has_course_access(p_course_id))
        -- A subtopic counts as part of its parent topic.
        and (coalesce(array_length(p_topic_ids, 1), 0) = 0 or q.topic_id = any (p_topic_ids) or t.parent_id = any (p_topic_ids))
        and (
          p_mode <> 'incorrect' or exists (
            select 1 from (
              select distinct on (a.question_id) a.question_id, a.is_correct
              from public.question_attempts a
              where a.user_id = v_user and a.question_id = q.id
              order by a.question_id, a.answered_at desc
            ) latest where not latest.is_correct
          )
        )
      -- Parts of one exam case stay together and in order within a topic session.
      order by case when p_mode = 'topic' then t.sort_order else 0 end,
               case when p_mode = 'topic' then q.exam_id end,
               case when p_mode = 'topic' then q.exam_position end,
               case when p_mode = 'topic' then q.created_at end,
               random()
      limit p_limit
    ) picked;
  end if;

  if v_ids is null then
    raise exception 'no_questions_available' using errcode = 'P0002';
  end if;

  insert into public.practice_sessions (user_id, course_id, mode, topic_ids, question_ids, time_limit_seconds, exam_id)
  values (v_user, p_course_id, p_mode, coalesce(p_topic_ids, '{}'), v_ids,
          case when p_mode = 'exam' then p_time_limit_seconds end, p_exam_id)
  returning id into v_session;

  return v_session;
end $$;

-- Records one answer of any type. Idempotent: a repeated submit returns the first recorded answer.
-- In exam mode feedback stays hidden until finish_practice_session.
create or replace function public.submit_response(p_session_id uuid, p_question_id uuid, p_response jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_user uuid := auth.uid();
  v_session public.practice_sessions;
  v_question public.questions;
  v_key public.question_answer_keys;
  v_attempt public.question_attempts;
  v_score numeric;
begin
  select * into v_session from public.practice_sessions where id = p_session_id and user_id = v_user;
  if not found then
    raise exception 'session_not_found' using errcode = 'P0002';
  end if;
  if v_session.finished_at is not null then
    raise exception 'session_finished' using errcode = '22023';
  end if;
  if not (p_question_id = any (v_session.question_ids)) then
    raise exception 'question_not_in_session' using errcode = '22023';
  end if;
  if v_session.mode = 'exam' and v_session.time_limit_seconds is not null
     and now() > v_session.started_at + make_interval(secs => v_session.time_limit_seconds) then
    raise exception 'time_expired' using errcode = '22023';
  end if;

  select * into v_question from public.questions where id = p_question_id;
  perform public.validate_response(v_question, p_response);

  select * into v_key from public.question_answer_keys where question_id = p_question_id;
  if not found or (v_question.type = 'single_choice' and v_key.correct_option_id is null) then
    raise exception 'answer_key_missing' using errcode = 'P0002';
  end if;

  v_score := public.grade_response(v_question, v_key, p_response);

  insert into public.question_attempts (user_id, session_id, question_id, selected_option_id, response, score, max_score, is_correct)
  values (v_user, p_session_id, p_question_id,
          case when v_question.type = 'single_choice' then (p_response ->> 'option_id')::uuid end,
          p_response, v_score, v_question.points, coalesce(v_score >= v_question.points, false))
  on conflict (session_id, question_id) do nothing;

  select * into v_attempt from public.question_attempts where session_id = p_session_id and question_id = p_question_id;

  if v_session.mode = 'exam' then
    return jsonb_build_object('recorded', true, 'selected_option_id', v_attempt.selected_option_id, 'response', v_attempt.response);
  end if;

  return jsonb_build_object(
    'recorded', true,
    'selected_option_id', v_attempt.selected_option_id,
    'response', v_attempt.response,
    'is_correct', v_attempt.is_correct,
    'score', v_attempt.score,
    'max_score', v_attempt.max_score,
    'needs_grading', v_attempt.score is null,
    'correct_option_id', v_key.correct_option_id,
    'answer', v_key.answer,
    'explanation', v_key.explanation,
    'concept', v_key.concept,
    'option_feedback', v_key.option_feedback
  );
end $$;

-- The single-choice entry point the app used before; kept so older clients keep working.
create or replace function public.submit_answer(p_session_id uuid, p_question_id uuid, p_option_id uuid)
returns jsonb
language sql security definer set search_path = public as $$
  select public.submit_response(p_session_id, p_question_id, jsonb_build_object('option_id', p_option_id));
$$;

-- The student marks their own open answer against the answer model, in steps of half a point.
-- In exam mode that is only possible once the exam has been handed in and the model answers are visible.
create or replace function public.self_grade(p_session_id uuid, p_question_id uuid, p_score numeric)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_user uuid := auth.uid();
  v_session public.practice_sessions;
  v_attempt public.question_attempts;
begin
  select * into v_session from public.practice_sessions where id = p_session_id and user_id = v_user;
  if not found then
    raise exception 'session_not_found' using errcode = 'P0002';
  end if;
  if v_session.mode = 'exam' and v_session.finished_at is null then
    raise exception 'grade_after_finish' using errcode = '22023';
  end if;
  select a.* into v_attempt from public.question_attempts a
  join public.questions q on q.id = a.question_id and q.type = 'open'
  where a.session_id = p_session_id and a.question_id = p_question_id;
  if not found then
    raise exception 'not_gradable' using errcode = '22023';
  end if;
  if p_score is null or p_score < 0 or p_score > v_attempt.max_score or p_score * 2 <> trunc(p_score * 2) then
    raise exception 'invalid_score' using errcode = '22023';
  end if;

  update public.question_attempts set score = p_score, is_correct = p_score >= max_score
  where id = v_attempt.id
  returning * into v_attempt;

  return jsonb_build_object('score', v_attempt.score, 'max_score', v_attempt.max_score, 'is_correct', v_attempt.is_correct);
end $$;

-- Closes a session and returns the score in points plus a full review (answer keys included).
create or replace function public.finish_practice_session(p_session_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_user uuid := auth.uid();
  v_session public.practice_sessions;
  v_review jsonb;
begin
  select * into v_session from public.practice_sessions where id = p_session_id and user_id = v_user;
  if not found then
    raise exception 'session_not_found' using errcode = 'P0002';
  end if;

  update public.practice_sessions set finished_at = coalesce(finished_at, now()) where id = p_session_id;

  select coalesce(jsonb_agg(jsonb_build_object(
      'question_id', s.qid,
      'selected_option_id', a.selected_option_id,
      'response', a.response,
      'is_correct', coalesce(a.is_correct, false),
      'score', a.score,
      'max_score', q.points,
      'needs_grading', a.id is not null and a.score is null,
      'correct_option_id', k.correct_option_id,
      'answer', coalesce(k.answer, '{}'::jsonb),
      'explanation', k.explanation,
      'concept', k.concept,
      'option_feedback', k.option_feedback
    ) order by s.ord), '[]'::jsonb)
  into v_review
  from unnest(v_session.question_ids) with ordinality as s(qid, ord)
  join public.questions q on q.id = s.qid
  left join public.question_attempts a on a.session_id = p_session_id and a.question_id = s.qid
  left join public.question_answer_keys k on k.question_id = s.qid;

  return jsonb_build_object(
    'total', coalesce(array_length(v_session.question_ids, 1), 0),
    'answered', (select count(*) from public.question_attempts where session_id = p_session_id),
    'correct', (select count(*) from public.question_attempts where session_id = p_session_id and is_correct),
    'points', (select coalesce(sum(points), 0) from public.questions where id = any (v_session.question_ids)),
    'scored', (select coalesce(sum(score), 0) from public.question_attempts where session_id = p_session_id),
    'review', v_review
  );
end $$;

revoke execute on function public.start_practice_session(uuid, public.practice_mode, uuid[], integer, integer, uuid) from public, anon;
revoke execute on function public.submit_response(uuid, uuid, jsonb) from public, anon;
revoke execute on function public.self_grade(uuid, uuid, numeric) from public, anon;
grant execute on function public.start_practice_session(uuid, public.practice_mode, uuid[], integer, integer, uuid) to authenticated;
grant execute on function public.submit_response(uuid, uuid, jsonb) to authenticated;
grant execute on function public.self_grade(uuid, uuid, numeric) to authenticated;

-- ===== supabase/migrations/20261030090000_hint_retry.sql =====
-- A second attempt with a hint from the summary. In practice modes (never in exam mode), a wrong answer to a
-- question that points at a summary section is not answered with the key straight away: the student reads the
-- section and gets one more attempt. The answer key is released only after that second attempt, or when the
-- student asks for it. A correct second attempt counts as correct, marked "with hint".

-- Which part of a summary helps with this question: {"summary_id": uuid, "heading": "<heading text>"}.
-- Not secret: it points at study material, not at the answer.
alter table public.questions
  add column hint jsonb check (hint is null or (jsonb_typeof(hint) = 'object' and hint ? 'summary_id' and hint ? 'heading'));

alter table public.question_attempts
  -- False while the student still has a second attempt to make.
  add column final boolean not null default true,
  add column attempts smallint not null default 1 check (attempts between 1 and 2),
  -- The student saw the hint before the final answer (a second attempt, or the answer shown after one).
  add column used_hint boolean not null default false;

-- The feedback for a final attempt: score, key and explanation.
create or replace function public.attempt_feedback(p_attempt public.question_attempts, p_key public.question_answer_keys)
returns jsonb
language sql stable set search_path = public as $$
  select jsonb_build_object(
    'recorded', true,
    'selected_option_id', p_attempt.selected_option_id,
    'response', p_attempt.response,
    'is_correct', p_attempt.is_correct,
    'score', p_attempt.score,
    'max_score', p_attempt.max_score,
    'needs_grading', p_attempt.score is null,
    'used_hint', p_attempt.used_hint,
    'attempts', p_attempt.attempts,
    'correct_option_id', p_key.correct_option_id,
    'answer', p_key.answer,
    'explanation', p_key.explanation,
    'concept', p_key.concept,
    'option_feedback', p_key.option_feedback
  );
$$;
revoke execute on function public.attempt_feedback(public.question_attempts, public.question_answer_keys) from public, anon, authenticated;

-- What a wrong first attempt may show without giving the answer away: the chosen option that is wrong, or which
-- drop-down items are wrong (not what they should be).
create or replace function public.retry_hint(p_question public.questions, p_key public.question_answer_keys, p_response jsonb)
returns jsonb
language sql stable set search_path = public as $$
  select jsonb_build_object(
    'retry', true,
    'response', p_response,
    'wrong_option_ids', case when p_question.type = 'single_choice' then jsonb_build_array(p_response ->> 'option_id') else '[]'::jsonb end,
    'wrong_items', case when p_question.type = 'dropdowns' then coalesce((
      select jsonb_agg(r.n - 1 order by r.n)
      from jsonb_array_elements(p_response -> 'answers') with ordinality r(v, n)
      where r.v is distinct from (p_key.answer -> 'answers' -> (r.n::int - 1))
    ), '[]'::jsonb) else '[]'::jsonb end
  );
$$;
revoke execute on function public.retry_hint(public.questions, public.question_answer_keys, jsonb) from public, anon, authenticated;

create or replace function public.submit_response(p_session_id uuid, p_question_id uuid, p_response jsonb)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_user uuid := auth.uid();
  v_session public.practice_sessions;
  v_question public.questions;
  v_key public.question_answer_keys;
  v_attempt public.question_attempts;
  v_score numeric;
  v_correct boolean;
  v_can_retry boolean;
  v_existing boolean;
begin
  select * into v_session from public.practice_sessions where id = p_session_id and user_id = v_user;
  if not found then
    raise exception 'session_not_found' using errcode = 'P0002';
  end if;
  if v_session.finished_at is not null then
    raise exception 'session_finished' using errcode = '22023';
  end if;
  if not (p_question_id = any (v_session.question_ids)) then
    raise exception 'question_not_in_session' using errcode = '22023';
  end if;
  if v_session.mode = 'exam' and v_session.time_limit_seconds is not null
     and now() > v_session.started_at + make_interval(secs => v_session.time_limit_seconds) then
    raise exception 'time_expired' using errcode = '22023';
  end if;

  select * into v_question from public.questions where id = p_question_id;
  select * into v_key from public.question_answer_keys where question_id = p_question_id;
  if not found or (v_question.type = 'single_choice' and v_key.correct_option_id is null) then
    raise exception 'answer_key_missing' using errcode = 'P0002';
  end if;

  perform public.validate_response(v_question, p_response);

  select * into v_attempt from public.question_attempts where session_id = p_session_id and question_id = p_question_id;
  v_existing := found;

  -- Already answered for good: return what was recorded (a repeated submit changes nothing).
  if v_existing and v_attempt.final then
    if v_session.mode = 'exam' then
      return jsonb_build_object('recorded', true, 'selected_option_id', v_attempt.selected_option_id, 'response', v_attempt.response);
    end if;
    return public.attempt_feedback(v_attempt, v_key);
  end if;

  v_score := public.grade_response(v_question, v_key, p_response);
  v_correct := coalesce(v_score >= v_question.points, false);

  -- The second attempt, after the hint: final whatever the outcome.
  if v_existing then
    update public.question_attempts set
      response = p_response,
      selected_option_id = case when v_question.type = 'single_choice' then (p_response ->> 'option_id')::uuid end,
      score = v_score, is_correct = v_correct, attempts = 2, used_hint = true, final = true, answered_at = now()
    where id = v_attempt.id
    returning * into v_attempt;
    return public.attempt_feedback(v_attempt, v_key);
  end if;

  -- A first wrong answer gets a second attempt with the hint, in practice modes, for auto-graded questions with a hint.
  v_can_retry := v_session.mode <> 'exam' and v_question.hint is not null and v_score is not null and not v_correct;

  insert into public.question_attempts (user_id, session_id, question_id, selected_option_id, response, score, max_score, is_correct, final)
  values (v_user, p_session_id, p_question_id,
          case when v_question.type = 'single_choice' then (p_response ->> 'option_id')::uuid end,
          p_response, v_score, v_question.points, v_correct, not v_can_retry)
  on conflict (session_id, question_id) do nothing
  returning * into v_attempt;

  -- A simultaneous duplicate submit (double click) lost the race: answer with what the first one recorded.
  if not found then
    select * into v_attempt from public.question_attempts where session_id = p_session_id and question_id = p_question_id;
    if v_session.mode = 'exam' then
      return jsonb_build_object('recorded', true, 'selected_option_id', v_attempt.selected_option_id, 'response', v_attempt.response);
    end if;
    if not v_attempt.final then
      return public.retry_hint(v_question, v_key, v_attempt.response);
    end if;
    return public.attempt_feedback(v_attempt, v_key);
  end if;

  if v_session.mode = 'exam' then
    return jsonb_build_object('recorded', true, 'selected_option_id', v_attempt.selected_option_id, 'response', v_attempt.response);
  end if;
  if v_can_retry then
    return public.retry_hint(v_question, v_key, p_response);
  end if;
  return public.attempt_feedback(v_attempt, v_key);
end $$;

-- The student gives up on the second attempt: the first (wrong) answer stands and the key is shown.
create or replace function public.reveal_answer(p_session_id uuid, p_question_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_user uuid := auth.uid();
  v_attempt public.question_attempts;
  v_key public.question_answer_keys;
begin
  if not exists (select 1 from public.practice_sessions where id = p_session_id and user_id = v_user) then
    raise exception 'session_not_found' using errcode = 'P0002';
  end if;
  update public.question_attempts set final = true, used_hint = true
  where session_id = p_session_id and question_id = p_question_id and not final
  returning * into v_attempt;
  if not found then
    select * into v_attempt from public.question_attempts where session_id = p_session_id and question_id = p_question_id;
    if not found or not v_attempt.final then
      raise exception 'nothing_to_reveal' using errcode = '22023';
    end if;
  end if;
  select * into v_key from public.question_answer_keys where question_id = p_question_id;
  return public.attempt_feedback(v_attempt, v_key);
end $$;

-- Finishing a session closes any second attempt that was never made.
create or replace function public.finish_practice_session(p_session_id uuid)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_user uuid := auth.uid();
  v_session public.practice_sessions;
  v_review jsonb;
begin
  select * into v_session from public.practice_sessions where id = p_session_id and user_id = v_user;
  if not found then
    raise exception 'session_not_found' using errcode = 'P0002';
  end if;

  update public.practice_sessions set finished_at = coalesce(finished_at, now()) where id = p_session_id;
  update public.question_attempts set final = true, used_hint = true where session_id = p_session_id and not final;

  select coalesce(jsonb_agg(jsonb_build_object(
      'question_id', s.qid,
      'selected_option_id', a.selected_option_id,
      'response', a.response,
      'is_correct', coalesce(a.is_correct, false),
      'score', a.score,
      'max_score', q.points,
      'needs_grading', a.id is not null and a.score is null,
      'used_hint', coalesce(a.used_hint, false),
      'attempts', coalesce(a.attempts, 0),
      'correct_option_id', k.correct_option_id,
      'answer', coalesce(k.answer, '{}'::jsonb),
      'explanation', k.explanation,
      'concept', k.concept,
      'option_feedback', k.option_feedback
    ) order by s.ord), '[]'::jsonb)
  into v_review
  from unnest(v_session.question_ids) with ordinality as s(qid, ord)
  join public.questions q on q.id = s.qid
  left join public.question_attempts a on a.session_id = p_session_id and a.question_id = s.qid
  left join public.question_answer_keys k on k.question_id = s.qid;

  return jsonb_build_object(
    'total', coalesce(array_length(v_session.question_ids, 1), 0),
    'answered', (select count(*) from public.question_attempts where session_id = p_session_id),
    'correct', (select count(*) from public.question_attempts where session_id = p_session_id and is_correct),
    'with_hint', (select count(*) from public.question_attempts where session_id = p_session_id and is_correct and used_hint),
    'points', (select coalesce(sum(points), 0) from public.questions where id = any (v_session.question_ids)),
    'scored', (select coalesce(sum(score), 0) from public.question_attempts where session_id = p_session_id),
    'review', v_review
  );
end $$;

-- Progress counts only what was right at the first go; "with hint" answers come back in "incorrect" practice.
create or replace function public.my_topic_stats(p_course_id uuid)
returns table (topic_id uuid, answered bigint, correct bigint)
language sql stable security definer set search_path = public as $$
  select q.topic_id, count(*), count(*) filter (where latest.is_correct and not latest.used_hint)
  from (
    select distinct on (a.question_id) a.question_id, a.is_correct, a.used_hint
    from public.question_attempts a
    where a.user_id = auth.uid() and a.final
    order by a.question_id, a.answered_at desc
  ) latest
  join public.questions q on q.id = latest.question_id
  where q.course_id = p_course_id
  group by q.topic_id;
$$;

create or replace function public.start_practice_session(
  p_course_id uuid,
  p_mode public.practice_mode,
  p_topic_ids uuid[] default '{}',
  p_limit integer default 20,
  p_time_limit_seconds integer default null,
  p_exam_id uuid default null
) returns uuid
language plpgsql security definer set search_path = public as $$
declare
  v_user uuid := auth.uid();
  v_ids uuid[];
  v_session uuid;
begin
  if v_user is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 200 then
    raise exception 'invalid_limit' using errcode = '22023';
  end if;
  if p_exam_id is null and p_mode = 'topic' and coalesce(array_length(p_topic_ids, 1), 0) <> 1 then
    raise exception 'topic_mode_needs_one_topic' using errcode = '22023';
  end if;

  if p_exam_id is not null then
    -- A whole exam, in its original order.
    select array_agg(id order by exam_position, created_at) into v_ids from (
      select q.id, q.exam_position, q.created_at
      from public.questions q
      join public.exams e on e.id = q.exam_id and e.status = 'published'
      where q.exam_id = p_exam_id
        and q.course_id = p_course_id
        and q.status = 'published'
        and (not q.is_premium or public.has_course_access(p_course_id))
      order by q.exam_position, q.created_at
      limit p_limit
    ) picked;
  else
    select array_agg(id) into v_ids from (
      select q.id
      from public.questions q
      join public.topics t on t.id = q.topic_id
      where q.course_id = p_course_id
        and q.status = 'published'
        and (not q.is_premium or public.has_course_access(p_course_id))
        -- A subtopic counts as part of its parent topic.
        and (coalesce(array_length(p_topic_ids, 1), 0) = 0 or q.topic_id = any (p_topic_ids) or t.parent_id = any (p_topic_ids))
        and (
          p_mode <> 'incorrect' or exists (
            select 1 from (
              select distinct on (a.question_id) a.question_id, a.is_correct, a.used_hint
              from public.question_attempts a
              where a.user_id = v_user and a.question_id = q.id and a.final
              order by a.question_id, a.answered_at desc
            ) latest where not latest.is_correct or latest.used_hint
          )
        )
      -- Parts of one exam case stay together and in order within a topic session.
      order by case when p_mode = 'topic' then t.sort_order else 0 end,
               case when p_mode = 'topic' then q.exam_id end,
               case when p_mode = 'topic' then q.exam_position end,
               case when p_mode = 'topic' then q.created_at end,
               random()
      limit p_limit
    ) picked;
  end if;

  if v_ids is null then
    raise exception 'no_questions_available' using errcode = 'P0002';
  end if;

  insert into public.practice_sessions (user_id, course_id, mode, topic_ids, question_ids, time_limit_seconds, exam_id)
  values (v_user, p_course_id, p_mode, coalesce(p_topic_ids, '{}'), v_ids,
          case when p_mode = 'exam' then p_time_limit_seconds end, p_exam_id)
  returning id into v_session;

  return v_session;
end $$;

revoke execute on function public.reveal_answer(uuid, uuid) from public, anon;
grant execute on function public.reveal_answer(uuid, uuid) to authenticated;

-- ===== supabase/migrations/20261031090000_flashcards_progress.sql =====
-- Flashcards per topic, studied Quizlet-style ("weet ik" / "nog niet") with a simple Leitner schedule, and one
-- read-only overview of a student's own progress in a course for the course page.
--
-- Leitner boxes: 0 = again (last answer "nog niet"), 1–5 = known, each box waits longer before the card is due again.
-- A card only moves up when it is due (or never known yet), so clicking "weet ik" ten times in one sitting does
-- not make a card "mastered": that takes recall on separate days. Mastered = box 2 or higher.

create table public.flashcards (
  id uuid primary key default gen_random_uuid(),
  course_id uuid not null references public.courses (id) on delete cascade,
  topic_id uuid not null references public.topics (id) on delete restrict,
  -- Both sides use the summary markup (bold, terms, formulas).
  front text not null check (length(front) between 1 and 500),
  back text not null check (length(back) between 1 and 4000),
  sort_order integer not null default 0,
  source text not null,
  copyright_status public.rights_status not null default 'unknown',
  is_premium boolean not null default true,
  reviewed_by uuid references auth.users (id),
  reviewed_at timestamptz,
  status public.publication_status not null default 'draft',
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  constraint flashcards_publishable check (
    status <> 'published'
    or (reviewed_at is not null and copyright_status in ('licensed', 'own_work', 'public_domain'))
  )
);
create index flashcards_topic on public.flashcards (topic_id, sort_order) where status = 'published';
create index flashcards_course on public.flashcards (course_id);
create trigger flashcards_touch before update on public.flashcards for each row execute function public.touch_updated_at();

alter table public.flashcards enable row level security;
create policy "flashcards readable with access" on public.flashcards for select using (
  public.is_admin() or (
    status = 'published' and auth.uid() is not null
    and (not is_premium or public.has_course_access(course_id))
  )
);
create policy "admins manage" on public.flashcards for all using (public.is_admin()) with check (public.is_admin());

create table public.flashcard_progress (
  user_id uuid not null references auth.users (id) on delete cascade,
  flashcard_id uuid not null references public.flashcards (id) on delete cascade,
  box smallint not null default 0 check (box between 0 and 5),
  reviews integer not null default 0,
  lapses integer not null default 0,
  last_known boolean not null,
  last_reviewed_at timestamptz not null default now(),
  due_at timestamptz not null default now(),
  primary key (user_id, flashcard_id)
);
create index flashcard_progress_due on public.flashcard_progress (user_id, due_at);

alter table public.flashcard_progress enable row level security;
-- Students read their own rows; every write goes through review_flashcard().
create policy "own flashcard progress readable" on public.flashcard_progress for select using (user_id = auth.uid());

create or replace function public.review_flashcard(p_flashcard_id uuid, p_known boolean)
returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_user uuid := auth.uid();
  v_card public.flashcards;
  v_row public.flashcard_progress;
  v_box smallint;
  v_promoted boolean;
begin
  if v_user is null then
    raise exception 'not_authenticated' using errcode = '28000';
  end if;
  select * into v_card from public.flashcards where id = p_flashcard_id and status = 'published';
  if not found or (v_card.is_premium and not public.has_course_access(v_card.course_id)) then
    raise exception 'flashcard_not_found' using errcode = 'P0002';
  end if;

  select * into v_row from public.flashcard_progress where user_id = v_user and flashcard_id = p_flashcard_id for update;
  if not found then
    v_row := row(v_user, p_flashcard_id, 0, 0, 0, false, now(), now())::public.flashcard_progress;
  end if;

  -- Known again before it was due: no promotion, the schedule stays as it was.
  v_promoted := p_known and (v_row.box = 0 or v_row.due_at <= now());
  v_box := case when not p_known then 0 when v_promoted then least(v_row.box + 1, 5) else v_row.box end;

  insert into public.flashcard_progress as p (user_id, flashcard_id, box, reviews, lapses, last_known, last_reviewed_at, due_at)
  values (
    v_user, p_flashcard_id, v_box, v_row.reviews + 1, v_row.lapses + (case when p_known then 0 else 1 end), p_known, now(),
    case when not p_known then now()
         when v_promoted then now() + (array[interval '1 day', interval '3 days', interval '7 days', interval '14 days', interval '30 days'])[v_box]
         else v_row.due_at
    end
  )
  on conflict (user_id, flashcard_id) do update
    set box = excluded.box, reviews = excluded.reviews, lapses = excluded.lapses, last_known = excluded.last_known,
        last_reviewed_at = excluded.last_reviewed_at, due_at = excluded.due_at
  returning * into v_row;

  return jsonb_build_object('box', v_row.box, 'due_at', v_row.due_at, 'last_known', v_row.last_known, 'reviews', v_row.reviews);
end $$;
revoke execute on function public.review_flashcard(uuid, boolean) from public, anon;
grant execute on function public.review_flashcard(uuid, boolean) to authenticated;

-- Flashcards per topic for the course page, without revealing the cards.
create or replace function public.course_content_overview(p_course_id uuid)
returns jsonb
language sql stable security definer set search_path = public as $$
  select jsonb_build_object(
    'summaries', (select count(*) from public.summaries s join public.topics t on t.id = s.topic_id
                  where t.course_id = p_course_id and s.status = 'published' and t.status = 'published'),
    'objectives', (select count(*) from public.learning_objectives o join public.topics t on t.id = o.topic_id
                   where t.course_id = p_course_id and o.status = 'published' and t.status = 'published'),
    'exams', (select count(*) from public.exams e where e.course_id = p_course_id and e.status = 'published'),
    'questions', (select count(*) from public.questions q where q.course_id = p_course_id and q.status = 'published'),
    'flashcards', (select count(*) from public.flashcards f where f.course_id = p_course_id and f.status = 'published'),
    'has_access', public.has_course_access(p_course_id)
  )
  where exists (select 1 from public.courses where id = p_course_id and status = 'published');
$$;

-- The viewer's own progress in a course: content covered per topic, practice results and recent exam simulations.
-- Coverage (what has been studied) and performance (how well) are reported separately.
create or replace function public.my_course_progress(p_course_id uuid)
returns jsonb
language sql stable security definer set search_path = public as $$
  with
  topics as (
    select t.id, t.title, t.slug, t.sort_order from public.topics t
    where t.course_id = p_course_id and t.status = 'published'
  ),
  latest as (
    select distinct on (a.question_id) a.question_id, a.is_correct, a.used_hint
    from public.question_attempts a
    join public.questions q on q.id = a.question_id and q.course_id = p_course_id
    where a.user_id = auth.uid() and a.final
    order by a.question_id, a.answered_at desc
  ),
  per_topic as (
    select t.id, t.title, t.slug, t.sort_order,
      (select count(*) from public.questions q where q.topic_id = t.id and q.status = 'published') as questions_total,
      (select count(*) from latest l join public.questions q on q.id = l.question_id where q.topic_id = t.id) as questions_answered,
      (select count(*) from latest l join public.questions q on q.id = l.question_id
        where q.topic_id = t.id and l.is_correct and not l.used_hint) as questions_correct,
      (select count(*) from public.flashcards f where f.topic_id = t.id and f.status = 'published') as flashcards_total,
      (select count(*) from public.flashcard_progress p join public.flashcards f on f.id = p.flashcard_id
        where p.user_id = auth.uid() and f.topic_id = t.id and f.status = 'published' and p.box >= 2) as flashcards_mastered,
      (select count(*) from public.flashcard_progress p join public.flashcards f on f.id = p.flashcard_id
        where p.user_id = auth.uid() and f.topic_id = t.id and f.status = 'published' and p.box = 1) as flashcards_learning,
      (select count(*) from public.flashcard_progress p join public.flashcards f on f.id = p.flashcard_id
        where p.user_id = auth.uid() and f.topic_id = t.id and f.status = 'published' and p.box = 0) as flashcards_again,
      (select count(*) from public.flashcard_progress p join public.flashcards f on f.id = p.flashcard_id
        where p.user_id = auth.uid() and f.topic_id = t.id and f.status = 'published' and p.due_at <= now()) as flashcards_due,
      (select count(*) from public.learning_objectives o where o.topic_id = t.id and o.status = 'published') as objectives_total,
      (select count(*) from public.objective_completions c join public.learning_objectives o on o.id = c.objective_id
        where c.user_id = auth.uid() and o.topic_id = t.id and o.status = 'published') as objectives_done
    from topics t
  )
  select jsonb_build_object(
    'answers_given', (select count(*) from public.question_attempts a join public.questions q on q.id = a.question_id
                      where a.user_id = auth.uid() and a.final and q.course_id = p_course_id),
    'to_repeat', (select count(*) from latest where not is_correct or used_hint),
    'topics', coalesce((select jsonb_agg(to_jsonb(p) order by p.sort_order) from per_topic p), '[]'::jsonb),
    'exams', coalesce((
      select jsonb_agg(x order by x.finished_at desc) from (
        select s.id, s.finished_at, e.title as exam_title, cardinality(s.question_ids) as questions,
          (select coalesce(sum(q.points), 0) from public.questions q where q.id = any (s.question_ids)) as points,
          (select coalesce(sum(a.score), 0) from public.question_attempts a where a.session_id = s.id) as scored
        from public.practice_sessions s
        left join public.exams e on e.id = s.exam_id
        where s.user_id = auth.uid() and s.course_id = p_course_id and s.mode = 'exam' and s.finished_at is not null
        order by s.finished_at desc
        limit 10
      ) x
    ), '[]'::jsonb)
  )
  where auth.uid() is not null;
$$;
revoke execute on function public.my_course_progress(uuid) from public, anon;
grant execute on function public.my_course_progress(uuid) to authenticated;

